import java.util.*;
// 用哈希表记录字符最近下标
class Solution {
    public int lengthOfLongestSubstring(String s) {
        // 最近位置用来判断重复字符是否还留在窗口里
        Map<Character, Integer> lastSeen = new HashMap<>();
        int left = 0;
        int longest = 0;
        for (int right = 0;
        right < s.length();
        right++) {
            char c = s.charAt(right);
            // 下标仍 ≥ left 时，左端只能跳到该次出现的下一位
            if (lastSeen.containsKey(c) && lastSeen.get(c) >= left) {
                left = lastSeen.get(c) + 1;
            }
            lastSeen.put(c, right);
            longest = Math.max(longest, right - left + 1);
        }
        return longest;
    }
}

import java.util.*;
class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0;
        int best = 0;
        for (int right = 0;
        right < fruits.length;
        right++) {
            // 把右端这棵树计入当前连续采摘段
            count.merge(fruits[right], 1, Integer::sum);
            while (count.size() > 2) {
                // 种类超过两个篮子，从左边整棵丢掉直到只剩两种
                int type = fruits[left++];
                int next = count.get(type) - 1;
                if (next == 0) count.remove(type);
                else count.put(type, next);
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

// 本入口合同：k≥0，种类、窗口长度和下标均以 Java UTF-16 char 代码单元计，不是 Unicode 码点。null、空串或 k=0 返回0；k<0 不在调用域内，入口不检查负 k。
import java.util.HashMap;
import java.util.Map;
class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (s == null || s.length() == 0 || k == 0) {
            return 0;
        }
        Map<Character, Integer> cnt = new HashMap<>();
        int left = 0, ans = 0;
        for (int right = 0;
        right < s.length();
        right++) {
            char c = s.charAt(right);
            cnt.put(c, cnt.getOrDefault(c, 0) + 1);
            // 种类超过 k 就缩左端，频次归零则删键
            while (cnt.size() > k) {
                char lc = s.charAt(left);
                cnt.put(lc, cnt.get(lc) - 1);
                if (cnt.get(lc) == 0) {
                    cnt.remove(lc);
                }
                left++;
            }
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

import java.util.*;
// 用 List 收集起点，用 Arrays 比较频次
class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> answer = new ArrayList<>();
        if (p.length() > s.length()) return answer;
        int[] need = new int[26];
        int[] window = new int[26];
        // 先定好目标频次和第一个等长窗口，后面只做滑动增量
        for (int i = 0;
        i < p.length();
        i++) {
            need[p.charAt(i) - 'a']++;
            window[s.charAt(i) - 'a']++;
        }
        if (Arrays.equals(need, window)) answer.add(0);
        // 右进左出后窗长仍等于 p，频次相同则起点为 left+1
        for (int right = p.length();
        right < s.length();
        right++) {
            window[s.charAt(right) - 'a']++;
            int left = right - p.length();
            window[s.charAt(left) - 'a']--;
            if (Arrays.equals(need, window)) {
                answer.add(left + 1);
            }
        }
        return answer;
    }
}

// LC567 原题：s1、s2 均非 null，长度各为1..10000，只含小写英文字母 a-z。26项计数以此为前提；空模式、其他字符或 null 的行为不属于此接口合同。
class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s2.length() < s1.length()) {
            return false;
        }
        int[] cnt = new int[26];
        for (char c : s1.toCharArray()) {
            cnt[c - 'a']++;
        }
        // need 表示还差多少个 s1 中的字符
        int left = 0, need = s1.length();
        for (int right = 0;
        right < s2.length();
        right++) {
            if (cnt[s2.charAt(right) - 'a']-- > 0) {
                need--;
            }
            // 窗口超长就弹出左端，并把多减的计数加回
            if (right - left + 1 > s1.length()) {
                if (++cnt[s2.charAt(left++) - 'a'] > 0) {
                    need++;
                }
            }
            if (need == 0) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;
class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> answer = new ArrayList<>();
        if (s == null || words == null || words.length == 0) return answer;
        int wordLength = Objects.requireNonNull(words[0]).length();
        if (wordLength == 0) throw new IllegalArgumentException("nonempty words");
        for (String w : words) {
            if (Objects.requireNonNull(w).length() != wordLength) {
                throw new IllegalArgumentException("equal word lengths");
            }
        }
        int wordCount = words.length;
        long totalLength = (long)wordLength * wordCount;
        if (s.length() < totalLength) return answer;
        Map<String, Integer> need = new HashMap<>();
        for (String word : words) {
            need.merge(word, 1, Integer::sum);
        }
        // 不同 offset 代表不同的“按单词长度对齐方式”。
        for (int offset = 0;
        offset < wordLength;
        offset++) {
            int left = offset;
            int usedWords = 0;
            Map<String, Integer> window = new HashMap<>();
            for (int right = offset;
            right <= s.length() - wordLength;
            right += wordLength) {
                String word = s.substring(right, right + wordLength);
                if (!need.containsKey(word)) {
                    // 只移出当前活动窗口内的词，不扫描 HashMap 保留容量。
                    while (usedWords > 0) {
                        String outgoing = s.substring(left, left + wordLength);
                        decrement(window, outgoing);
                        left += wordLength;
                        usedWords--;
                    }
                    usedWords = 0;
                    left = right + wordLength;
                    continue;
                }
                window.merge(word, 1, Integer::sum);
                usedWords++;
                // 当前单词出现过多，左侧按完整单词收缩。
                while (window.get(word) > need.get(word)) {
                    String outgoing = s.substring(left, left + wordLength);
                    decrement(window, outgoing);
                    left += wordLength;
                    usedWords--;
                }
                if (usedWords == wordCount) {
                    answer.add(left);
                    // 主动移出最左单词，继续寻找可能重叠的下一个答案。
                    String outgoing = s.substring(left, left + wordLength);
                    decrement(window, outgoing);
                    left += wordLength;
                    usedWords--;
                }
            }
        }
        return answer;
    }
    private static void decrement(Map<String, Integer> counts, String word) {
        int count = counts.get(word);
        if (count == 1) counts.remove(word);
        else counts.put(word, count - 1);
    }
}

// LC76 原题：s、t 均非 null，长度各为1..100000，只含大小写英文字母。因字符都在 ASCII 内，主实现的128项数组下标合法；专题中的 ACM 实现也沿用非空目标。主入口额外在空 t 时返回空串，不代表所有专题模板具有同一扩展行为。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty() || s.length() < t.length()) return "";
        // need[c] 表示当前窗口还欠多少个 c，用来判断是否补上了真实需求。
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length();
        int left = 0;
        int bestStart = 0;
        int bestLength = Integer.MAX_VALUE;
        for (int right = 0;
        right < s.length();
        right++) {
            char incoming = s.charAt(right);
            // 原来还欠这个字符时，吃进它才算补上一个需求。
            if (need[incoming] > 0) missing--;
            need[incoming]--;
            // 已覆盖 t 后尽量右移左边界，才能得到更短的合法窗口。
            while (missing == 0) {
                int length = right - left + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = left;
                }
                char outgoing = s.charAt(left++);
                need[outgoing]++;
                // 归还后重新变成正数，说明移走的是必需字符，窗口不再合法。
                if (need[outgoing] > 0) missing++;
            }
        }
        return bestLength == Integer.MAX_VALUE
        ? ""
        : s.substring(bestStart, bestStart + bestLength);
    }
}

// LC209 原题：1<=target<=1000000000，1<=n<=100000，1<=nums[i]<=10000；总和<=1000000000。
class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int left = 0;
        int sum = 0;
        int ans = Integer.MAX_VALUE;
        for (int right = 0;
        right < nums.length;
        right++) {
            sum += nums[right];
            // 正数保证右扩只会变大，和够了就可以尽量丢掉左边
            while (sum >= target) {
                ans = Math.min(ans, right - left + 1);
                sum -= nums[left++];
            }
        }
        return ans == Integer.MAX_VALUE ? 0 : ans;
    }
}

import java.util.HashMap;
import java.util.Map;
public class MinWindowSubstringVariant {
    public String minWindow(String s, String t) {
        if (s == null || t == null || t.isEmpty() || s.length() < t.length()) {
            return "";
        }
        // 按出现次数记账，后面才能判断窗口是否盖住整个 t
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) {
            need.put(c, need.getOrDefault(c, 0) + 1);
        }
        // 只记 t 里出现过的字符，无关字符不参与是否覆盖的判断
        Map<Character, Integer> window = new HashMap<>();
        int left = 0;
        int right = 0;
        int valid = 0;
        // 已经达到 need 次数的字符种类数
        int start = 0;
        int minLen = Integer.MAX_VALUE;
        while (right < s.length()) {
            char c = s.charAt(right);
            right++;
            // 先扩右端，当前窗口是 [left, right)
            // 次数刚达标才让 valid 加一，避免重复计数
            if (need.containsKey(c)) {
                window.put(c, window.getOrDefault(c, 0) + 1);
                if (window.get(c).intValue() == need.get(c).intValue()) {
                    valid++;
                }
            }
            // 已经覆盖就缩左端，才能逼出更短的合法子串
            while (valid == need.size()) {
                if (right - left < minLen) {
                    start = left;
                    minLen = right - left;
                }
                char d = s.charAt(left);
                left++;
                // 移出前若该字符刚好达标，移出后窗口不再覆盖
                if (need.containsKey(d)) {
                    if (window.get(d).intValue() == need.get(d).intValue()) {
                        valid--;
                    }
                    window.put(d, window.get(d) - 1);
                }
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
    }
}

class Solution {
    public int longestSubstring(String s, int k) {
        if (s == null || s.length() == 0 || k > s.length()) return 0;
        if (k <= 1) return s.length();
        int answer = 0;
        for (int targetUnique = 1;
        targetUnique <= 26;
        targetUnique++) {
            int[] count = new int[26];
            int left = 0;
            int unique = 0;
            // 当前窗口里不同字符的个数
            int atLeastK = 0;
            // 其中频次已经达到 k 的字符个数
            for (int right = 0;
            right < s.length();
            right++) {
                int in = s.charAt(right) - 'a';
                if (count[in] == 0) unique++;
                count[in]++;
                if (count[in] == k) atLeastK++;
                // 种类超过本轮上限时，左端按进入时的相反规则退出
                while (unique > targetUnique) {
                    int out = s.charAt(left++) - 'a';
                    if (count[out] == k) atLeastK--;
                    count[out]--;
                    if (count[out] == 0) unique--;
                }
                // 种类刚好且每个都至少 k 次，这段才满足题意
                if (unique == targetUnique && atLeastK == unique) {
                    answer = Math.max(answer, right - left + 1);
                }
            }
        }
        return answer;
    }
}

import java.util.*;
public final class LongestOnes {
    public record Window(int start,int end){
        public int length(){
            return end-start;
        }
    }
    private LongestOnes(){
    }
    private static Window scan(int[] a,int k){
        int left=0,zeros=0,bestStart=0,bestEnd=0;
        for(int right=0;right<a.length;right++){
            if(a[right]==0)zeros++;
            while(zeros>k)if(a[left++]==0)zeros--;
            if(right-left+1>bestEnd-bestStart){
                bestStart=left;
                bestEnd=right+1;
            }
        }
        return new Window(bestStart,bestEnd);
    }
    public static Window atMost(int[] a,int k){
        validate(a,k);
        return scan(a,k);
    }
    public static Optional<Window> exactly(int[] a,int k){
        int zeros=validate(a,k);
        return zeros<k?Optional.empty():Optional.of(scan(a,k));
    }
    private static int runAfterFlips(int[] a,int flips){
        int best=0,run=0;
        for(int i=0;i<a.length;i++){
            boolean one=a[i]==1||(flips&(1<<i))!=0;
            run=one?run+1:0;
            best=Math.max(best,run);
        }
        return best;
    }
}
